Lemma frame_shad_in : forall FSB c p, FSB mod 4096 = 0 -> (c = 0 \/ c = 1 \/ c = 6 \/ c = 2 \/ c = 3 \/ c = 4 \/ c = 7) -> 0 <= p < NF c ->
